 static void Test(){Data=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"test-settings.txt");if(File.Exists(Data))File.Delete(Data);var s=new Session();Check(!s.Visible&&!s.Running,"Manual startup");s.Play();s.Advance(60);Check(s.Seconds==60,"Minute progress");s.Pause();s.Advance(100);Check(s.Seconds==60&&s.Visible,"Pause freeze");s.Play();s.Advance(1740);Check(s.Seconds==1800&&!s.Running&&s.Visible,"30 minute end hold");s.Play();Check(s.Seconds==0&&s.Running,"Replay");s.Stop();Check(!s.Visible&&s.Seconds==0,"Stop");Check(Session.ColorAt(0)==Color.FromArgb(255,220,0)&&Session.ColorAt(600)==Color.FromArgb(255,110,0)&&Session.ColorAt(1200)==Color.FromArgb(255,0,0)&&Session.ColorAt(1800)==Color.FromArgb(110,0,0),"Color anchors");for(int i=1;i<=30;i++)Check(Session.ColorAt(i*60)!=Session.ColorAt((i-1)*60),"Every minute changes color");
 Check(Math.Abs((Sun.SunsetUtc(new DateTime(2026,6,21),52.37,4.90).Value-new DateTime(2026,6,21,20,7,0)).TotalMinutes)<6,"Sunset Amsterdam June");Check(Math.Abs((Sun.SunsetUtc(new DateTime(2026,12,21),52.37,4.90).Value-new DateTime(2026,12,21,15,29,0)).TotalMinutes)<6,"Sunset Amsterdam December");Check(Sun.SunsetUtc(new DateTime(2026,6,21),78.2,15.6)==null,"Midnight sun");
 foreach(double duration in new[]{180.0,30.0}){s.Start(duration);Check(s.CurrentColor==Session.ColorAt(0),"Test starts yellow");s.Advance(duration/3);Check(s.CurrentColor==Session.ColorAt(600),"Test orange");s.Pause();s.Advance(50);Check(s.Seconds==duration/3,"Test pause");s.Play();s.Advance(duration/3);Check(s.CurrentColor==Session.ColorAt(1200),"Test red");s.Advance(duration/3);Check(s.Seconds==duration&&!s.Running&&s.CurrentColor==Session.ColorAt(1800),"Test dark red endpoint");s.Stop();Check(s.Duration==1800&&!s.Visible,"Normal mode restored");}
 s=new Session();s.SetNormal(3600);Check(s.Duration==3600,"Duration choice");s.Play();s.Advance(1200);Check(s.CurrentColor==Session.ColorAt(600),"60 minute color scale");s.Stop();Check(s.Duration==3600,"Chosen duration kept after stop");
 s.EndAction=1;s.Play();s.Advance(3600);Check(s.Fading&&s.Visible&&s.Opacity==1,"Fade starts at end");s.Advance(30);Check(Math.Abs(s.Opacity-0.5)<1e-9,"Fade halfway");s.Advance(30);Check(!s.Visible&&!s.Fading,"Fade ends with stop");s.Start(30);s.Advance(30);Check(s.Fading&&s.FadeDuration==5,"Short fade in test");s.Advance(5);Check(!s.Visible&&s.Duration==3600,"Test fade restores chosen duration");
 s.EndAction=2;s.Start(30);s.Advance(30);Check(!s.SleepPending&&s.Visible,"No sleep during test");s.Stop();s.Play();s.Advance(3600);Check(s.SleepPending,"Sleep requested at end");
 using(var f=new Sunset(true)){f.Show();Application.DoEvents();f.play.PerformClick();Check(f.session.Running,"Play button");f.pause.PerformClick();Check(!f.session.Running&&f.session.Visible,"Pause button");f.stop.PerformClick();Check(!f.session.Visible,"Stop button");f.test3.PerformClick();Check(f.session.Duration==180&&f.session.Running,"3 minute test button");f.test30.PerformClick();Check(f.session.Duration==30&&f.session.Seconds==0,"30 second test button restart");f.stop.PerformClick();
 f.duration.SelectedIndex=2;f.ending.SelectedIndex=1;Check(f.session.Duration==3600&&f.session.EndAction==1,"Duration and ending controls");f.TogglePlay();Check(f.session.Running,"Hotkey play");f.TogglePlay();Check(!f.session.Running&&f.session.Visible,"Hotkey pause");f.stop.PerformClick();
 f.SetAutostart(false);f.quiet=true;f.autostart.Checked=false;f.quiet=false;f.autostart.Checked=true;Check(f.AutostartEnabled(),"Autostart on");f.autostart.Checked=false;Check(!f.AutostartEnabled(),"Autostart off");
 f.startPicker.Value=DateTime.Today.AddHours(18);f.scheduled.Checked=true;Check(f.startMinutes==1080,"Start time picker");var day=new DateTime(2026,11,2);Check(!f.CheckSchedule(day.AddHours(17).AddMinutes(59)),"Not before start");Check(f.CheckSchedule(day.AddHours(18).AddMinutes(10))&&f.session.Visible&&!f.session.IsTest&&Math.Abs(f.session.Seconds-600)<1,"Late start catches up");f.stop.PerformClick();Check(!f.CheckSchedule(day.AddHours(18).AddMinutes(15)),"Runs once per day");Check(!f.CheckSchedule(day.AddDays(1).AddHours(19)),"Not after window");Check(f.CheckSchedule(day.AddDays(1).AddHours(18)),"Next day again");f.stop.PerformClick();
 f.sugStart.PerformClick();Check(f.startMinutes==f.SunToday().Value&&f.scheduled.Checked,"Suggestion fills start time");f.follow.Checked=true;f.sugLater.PerformClick();var dec=new DateTime(2026,12,21);Check(f.offsetMinutes==60&&f.StartMinutesFor(dec)==Sun.SunsetMinutes(dec,f.city.SelectedIndex).Value+60,"Follow sunset offset");
 foreach(int lang in new[]{0,1}){f.language.SelectedIndex=lang;Application.DoEvents();Check(f.ending.SelectedIndex==1,"Ending kept on language change");using(var b=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(b,new Rectangle(Point.Empty,b.Size));b.Save(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,lang==0?"preview-nl.png":"preview-en.png"));}}f.strength.Value=32;f.save.PerformClick();}using(var f=new Sunset(true)){Check(f.English&&f.strength.Value==32&&f.duration.SelectedIndex==2&&f.ending.SelectedIndex==1&&f.session.Duration==3600&&f.scheduled.Checked&&f.follow.Checked&&f.offsetMinutes==60&&f.lastRun==new DateTime(2026,11,3)&&!f.session.Visible,"Persistence without auto start");}
 using(var f=new Sunset(true,true)){f.Show();Application.DoEvents();Check(!f.Visible&&f.IsHandleCreated&&!f.session.Visible,"Tray start hidden without glow");f.Open();Application.DoEvents();Check(f.Visible,"Open from tray");}File.Delete(Data);File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"self-test.txt"),"PASS: 3-minute and 30-second test buttons, color anchors at both speeds, test pause and stop, normal duration restored, play/pause/resume/stop/replay, 30-minute end, 31 color points, duration choice 15/30/60/90 with color scaling, fade-out end, sleep end (requested only, not executed; never in tests), hotkey play/pause toggle, start-with-Windows on/off (test registry value), hidden tray start without glow, sunset calculation (June/December/midnight sun), scheduled start once per day with late catch-up, sunset suggestions and follow-sunset offset, NL/EN rendering, language/strength/duration/ending persistence, no automatic startup. Full live display and real sleep not timed.");}
